// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Unit tests for the aa-conf-main.json tunables
// Flo: apply JSON text > assert tune values, defaults on bad input
// I/O: JSON text > pass or fail
// ===================================================================
const std = @import("std"); const stor = @import("st-conf-stor.zig"); const tszz = std.testing;
test "empty object keeps every default, no warning" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{}") == null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); try tszz.expectEqual(@as(u32, 4), stor.tune.workers); try tszz.expectEqual(@as(u32, 64), stor.tune.hist_maxz); try tszz.expectEqual(@as(u32, 86400), stor.tune.tmoz_seco); try tszz.expectEqualStrings(".zz-base-home-tena/ac-auto-task", stor.tune.data); }
test "valid keys override, unknown keys are ignored" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{\"port\":4040,\"jobs_same_time\":2,\"cmds_hist_maxz\":50,\"time_limi_seco\":120,\"apps_data_loca_wind\":\".my-state\",\"apps_data_loca_unix\":\".my-state\",\"zzz\":1}") == null); try tszz.expectEqual(@as(u16, 4040), stor.tune.port); try tszz.expectEqual(@as(u32, 2), stor.tune.workers); try tszz.expectEqual(@as(u32, 50), stor.tune.hist_maxz); try tszz.expectEqual(@as(u32, 120), stor.tune.tmoz_seco); try tszz.expectEqualStrings(".my-state", stor.tune.data); }
test "out-of-range and wrong-type values fall back to defaults and warn" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{\"port\":0,\"jobs_same_time\":9,\"cmds_hist_maxz\":\"x\",\"time_limi_seco\":99999999,\"apps_data_loca_wind\":\"../up\",\"apps_data_loca_unix\":\"../up\"}") != null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); try tszz.expectEqual(@as(u32, 4), stor.tune.workers); try tszz.expectEqual(@as(u32, 64), stor.tune.hist_maxz); try tszz.expectEqual(@as(u32, 86400), stor.tune.tmoz_seco); try tszz.expectEqualStrings(".zz-base-home-tena/ac-auto-task", stor.tune.data); }
test "one bad key does not drop the good ones" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{\"port\":4041,\"jobs_same_time\":0}") != null); try tszz.expectEqual(@as(u16, 4041), stor.tune.port); try tszz.expectEqual(@as(u32, 4), stor.tune.workers); }
test "broken JSON and non-object roots use defaults and warn" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expect(stor.confApply(aren.allocator(), "{oops") != null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); try tszz.expect(stor.confApply(aren.allocator(), "[1]") != null); try tszz.expectEqual(@as(u16, 4000), stor.tune.port); }
test "envi_mode: fresh is the default; login and inherit switch it; a bad value warns" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); try tszz.expect(stor.confApply(allo, "{}") == null); try tszz.expect(stor.tune.envi_fres and !stor.tune.envi_logi); try tszz.expect(stor.confApply(allo, "{\"envi_mode\":\"login\"}") == null); try tszz.expect(stor.tune.envi_fres and stor.tune.envi_logi); try tszz.expect(stor.confApply(allo, "{\"envi_mode\":\"inherit\"}") == null); try tszz.expect(!stor.tune.envi_fres and !stor.tune.envi_logi); try tszz.expect(stor.confApply(allo, "{\"envi_mode\":\"fresh\"}") == null); try tszz.expect(stor.tune.envi_fres and !stor.tune.envi_logi); try tszz.expect(stor.confApply(allo, "{\"envi_mode\":\"weird\"}") != null); try tszz.expect(stor.tune.envi_fres and !stor.tune.envi_logi); try tszz.expect(stor.confApply(allo, "{\"envi_mode\":5}") != null); try tszz.expect(stor.tune.envi_fres); _ = stor.confApply(allo, "{}"); }
test "enviMap keeps the launch env and enviDiff never lists a value" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); _ = stor.confApply(allo, "{\"envi_mode\":\"inherit\"}"); defer _ = stor.confApply(allo, "{}"); var mapz = try stor.enviMap(allo); try tszz.expect(mapz.count() > 0); const names = try stor.enviDiff(allo); for (names) |name| try tszz.expect(name.len > 0 and std.mem.indexOfScalar(u8, name, '=') == null); }
test "lock_list: lock name to ids or prefixes; longest wins, no match is main, a repeated id keeps the first, bad entries warn" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); defer _ = stor.confApply(aren.allocator(), "{}"); try tszz.expectEqualStrings("main", stor.lockOf("scra-raws")); try tszz.expect(stor.confApply(aren.allocator(), "{\"lock_list\":{\"scra\":[\"scra-\"],\"raws\":[\"scra-raws\"],\"cicd\":[\"cicd-\",\"home-doct\"],\"none\":[\"bg-\"]}}") == null); try tszz.expectEqualStrings("scra", stor.lockOf("scra-data")); try tszz.expectEqualStrings("raws", stor.lockOf("scra-raws")); try tszz.expectEqualStrings("cicd", stor.lockOf("cicd-test")); try tszz.expectEqualStrings("cicd", stor.lockOf("home-doct")); try tszz.expectEqualStrings("main", stor.lockOf("home-code")); try tszz.expectEqualStrings("none", stor.lockOf("bg-x")); try tszz.expect(stor.confApply(aren.allocator(), "{\"lock_list\":{\"a\":[\"x-\"],\"b\":[\"x-\",7,\"\"],\"c\":\"y-\"}}") != null); try tszz.expectEqualStrings("a", stor.lockOf("x-1")); try tszz.expectEqualStrings("main", stor.lockOf("y-1")); try tszz.expect(stor.confApply(aren.allocator(), "{\"lock_list\":[1]}") != null); try tszz.expectEqualStrings("main", stor.lockOf("x-1")); }
test "jobs_same_time accepts 1 to 8 and rejects 9" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); defer _ = stor.confApply(aren.allocator(), "{}"); try tszz.expect(stor.confApply(aren.allocator(), "{\"jobs_same_time\":8}") == null); try tszz.expectEqual(@as(u32, 8), stor.tune.workers); try tszz.expect(stor.confApply(aren.allocator(), "{\"jobs_same_time\":9}") != null); try tszz.expectEqual(@as(u32, 4), stor.tune.workers); }
